PRAGMA foreign_keys = ON;
CREATE TABLE users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at TEXT NOT NULL);
CREATE INDEX sessions_user ON sessions(user_id);
CREATE TABLE rate_limits (key TEXT PRIMARY KEY, hits INTEGER NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE password_resets (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at TEXT NOT NULL);
CREATE TABLE niches (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', colour TEXT NOT NULL DEFAULT '#c6f66b', initials TEXT NOT NULL DEFAULT 'N', brand_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL);
CREATE INDEX niches_owner ON niches(user_id);
CREATE TABLE accounts (id TEXT PRIMARY KEY, niche_id TEXT NOT NULL REFERENCES niches(id), platform TEXT NOT NULL CHECK(platform IN ('facebook','instagram','tiktok','youtube')), display_name TEXT NOT NULL, provider_id TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'disconnected', encrypted_tokens TEXT, UNIQUE(niche_id,platform,provider_id));
CREATE TABLE media (id TEXT PRIMARY KEY, niche_id TEXT NOT NULL REFERENCES niches(id), object_key TEXT NOT NULL UNIQUE, filename TEXT NOT NULL, mime TEXT NOT NULL, size INTEGER NOT NULL, source_project TEXT, source_candidate TEXT, created_at TEXT NOT NULL, UNIQUE(niche_id,source_project,source_candidate));
CREATE INDEX media_niche ON media(niche_id);
CREATE TABLE posts (id TEXT PRIMARY KEY, niche_id TEXT NOT NULL REFERENCES niches(id), media_id TEXT REFERENCES media(id), title TEXT NOT NULL DEFAULT '', caption TEXT NOT NULL DEFAULT '', destinations_json TEXT NOT NULL DEFAULT '[]', overrides_json TEXT NOT NULL DEFAULT '{}', status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','scheduled','export_ready','blocked','cancelled')), scheduled_at TEXT, approved_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX posts_due ON posts(status,scheduled_at);
CREATE TABLE publications (id TEXT PRIMARY KEY, post_id TEXT NOT NULL REFERENCES posts(id), account_id TEXT NOT NULL REFERENCES accounts(id), status TEXT NOT NULL DEFAULT 'pending', provider_post_id TEXT, error TEXT, attempt INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL, UNIQUE(post_id,account_id));
CREATE TABLE clip_projects (project_id TEXT PRIMARY KEY, niche_id TEXT NOT NULL REFERENCES niches(id), created_at TEXT NOT NULL);
CREATE TABLE ideas (id TEXT PRIMARY KEY, niche_id TEXT NOT NULL REFERENCES niches(id), text TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'idea', created_at TEXT NOT NULL);
CREATE TABLE revenue (id TEXT PRIMARY KEY, niche_id TEXT NOT NULL REFERENCES niches(id), amount_pence INTEGER NOT NULL, category TEXT NOT NULL, note TEXT NOT NULL, earned_at TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE notifications (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), niche_id TEXT REFERENCES niches(id), message TEXT NOT NULL, read_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE audit_events (id TEXT PRIMARY KEY, user_id TEXT REFERENCES users(id), niche_id TEXT REFERENCES niches(id), action TEXT NOT NULL, resource_id TEXT, created_at TEXT NOT NULL);
